const fs = require("node:fs");
const path = require("node:path");
const { execFileSync } = require("node:child_process");
const { createRequire } = require("node:module");

const PACKAGE_SPECS = {
  imapflow: "imapflow@^1",
  nodemailer: "nodemailer@^7",
  mailparser: "mailparser@^3",
};

let runtimeRequire = null;
let installed = false;

function runtimeRoot() {
  if (process.env.CRM_MAIL_MODULE_ROOT) return process.env.CRM_MAIL_MODULE_ROOT;
  if (process.env.CRM_DB_PATH) {
    return path.join(path.dirname(process.env.CRM_DB_PATH), "mail-runtime");
  }
  return path.join(process.cwd(), "data", "mail-runtime");
}

function getRequire() {
  const root = runtimeRoot();
  const packageFile = path.join(root, "package.json");
  fs.mkdirSync(root, { recursive: true });
  if (!fs.existsSync(packageFile)) {
    fs.writeFileSync(
      packageFile,
      JSON.stringify({ name: "satori-mail-runtime", private: true }, null, 2),
      "utf8"
    );
  }
  if (!runtimeRequire) runtimeRequire = createRequire(packageFile);
  return { root, req: runtimeRequire };
}

function canResolve(req, name) {
  try {
    req.resolve(name);
    return true;
  } catch {
    return false;
  }
}

function ensureInstalled() {
  const { root, req } = getRequire();
  if (installed || Object.keys(PACKAGE_SPECS).every((name) => canResolve(req, name))) {
    installed = true;
    return req;
  }

  const npm = path.join(path.dirname(process.execPath), process.platform === "win32" ? "npm.cmd" : "npm");
  const env = {
    ...process.env,
    PATH: `${path.dirname(process.execPath)}${path.delimiter}${process.env.PATH || ""}`,
    npm_config_audit: "false",
    npm_config_fund: "false",
    npm_config_update_notifier: "false",
  };

  try {
    execFileSync(
      npm,
      [
        "install",
        "--omit=dev",
        "--no-audit",
        "--no-fund",
        "--prefix",
        root,
        ...Object.values(PACKAGE_SPECS),
      ],
      { env, stdio: "pipe", timeout: 90000 }
    );
  } catch (error) {
    const detail = error && error.stderr ? String(error.stderr).slice(-1200) : String(error && error.message ? error.message : error);
    throw new Error(`Не удалось подготовить почтовый модуль CRM: ${detail}`);
  }

  runtimeRequire = createRequire(path.join(root, "package.json"));
  installed = true;
  return runtimeRequire;
}

function load(name) {
  if (!PACKAGE_SPECS[name]) throw new Error(`Неизвестный почтовый модуль: ${name}`);
  return ensureInstalled()(name);
}

module.exports = { load };
